import { View, Text, StyleSheet } from "react-native";
import { registerRootComponent } from "expo";

function App() {
  return (
    <View style={styles.screen}>
      <View nativeID="header" style={styles.header}>
        <Text style={styles.brand}>Shop.mn</Text>
        <Text style={styles.cart}>Сагс: 3</Text>
        {/* энд бичнэ үү: header-ийг мөр болгож, хоёр талд түлх */}
      </View>
    </View>
  );
}

const styles = StyleSheet.create({
  screen: { flex: 1 },
  header: { padding: 16, backgroundColor: "#2563eb" },
  brand: { color: "#ffffff", fontSize: 20, fontWeight: "bold" },
  cart: { color: "#ffffff", fontSize: 14 },
});

registerRootComponent(App);

